  "customer.m628e39a94703": "공식 문서",
  "customer.m62c66a7a5dd7": "m",
  "customer.m6391e6d6580c": "저희는 안전하고 효율적으로 거래를 실행하는 것이 얼마나 중요한지 잘 알고 있습니다. 그렇기 때문에 저희는 24시간 내내 운영되며, 전 세계 은행 및 전자지갑 네트워크를 활용하여 고객에게 최상의 서비스를 제공합니다. 신속하고 안전하게 거래를 처리하는 저희를 믿고 맡겨주세요.",
  "customer.m64cecb8a6ef3": "메모",
