  "customer.m66f9b755298c": "24시간 변동",
  "customer.m675b66b1464b": "암호화폐 간 교환을 위해 독점적으로 구축되었습니다. 전환은 자동화된 입금 주소와 QR 코드를 생성하며, 자금이 도착하는 즉시 거래를 처리하기 위해 블록체인을 모니터링합니다.",
  "customer.m6761c45da3b7": "이 주문에 할당된 주소와 네트워크만 사용하십시오.",
  "customer.m67f709142079": "최소:",
