  "customer.m6976f9bca098": "교환은 AML 확인과 함께 자동으로 처리됩니다. 환율은 실시간 현물 시장 데이터를 기반으로 하는 변동 환율이며, 처리 시점의 현재 시장 상황에 따라 계산됩니다. 거래는 암호화폐와 네트워크에 따라 네트워크 확인이 필요합니다. 필수 확인이 완료되면 처리가 시작되며 추가로 최대 10분이 소요될 수 있습니다. 최종 금액은 시장 변동에 따라 달라질 수 있습니다.",
