  "customer.m76c28ab6335d": "자주 묻는 질문",
  "customer.m6acc6ebd3f58": "text-[8px]",
  "customer.mc93a0125ded0": "text-[9px]",
  "customer.mb72aa61c792e": "text-[10px]",
  "customer.m316975997a13": "주문을 찾을 수 없거나 해당 주문을 볼 수 있는 권한이 없습니다.",
  "customer.m84dfe738c172": "신원 확인 및 AML 정책 | QuickXchange",
  "customer.md61f745bf890": "QuickXchange의 신원 확인, 자금 출처, 거래 검토 및 자금 세탁 방지 정책을 읽어보십시오.",
  "customer.m2132a092ad46": "AML 정책은 QuickXchange가 신원 확인, 자금 출처 확인, 의심스러운 거래 검토, 사용자 협조 및 법적 정보 요청에 적용하는 원칙을 명시합니다. 이 정책은 확인 또는 강화된 검토가 필요한 사용자와 거래에 적용됩니다.",
  "customer.m516a382f29dc": "신원 확인 및 자금 세탁 방지(AML) 정책",
  "customer.m09095e212de1": "1.1. 본 AML 정책의 주요 목적은 투명성, 보안 및 거래 무결성을 증진하고, 불법 자금 유통 및 범죄 활동을 방지하기 위한 국제 및 국내 요구 사항을 준수하도록 지원하는 것입니다. 1.2. 이 정책은 신원 확인, 자금 출처 확인, 의심스러운 거래 식별 및 위반 혐의와 관련하여 필요한 경우 법 집행 기관과의 상호 작용을 다룹니다.",
  "customer.m9fca3e62fc23": "1. 정책의 목적",
  "customer.m482c03f2e3e0": "2.1. 사용자는 플랫폼 서비스에 액세스하기 위해 신원 확인을 완료해야 할 수 있습니다. 이 요구 사항은 플랫폼과 사용자를 사기 및 기타 금지된 활동으로부터 보호하는 데 도움이 됩니다. 2.2. 등록, 서비스 사용 또는 거래 검토 중에 요청되는 문서에는 다음이 포함될 수 있습니다: • 여권 메인 페이지 또는 앞면. • 여권 두 번째 페이지 또는 뒷면. • 은행 명세서, 공과금 고지서 또는 여권에 표시된 주소 등록과 같은 거주지 증명. 2.3. 필요한 경우, 계약자는 사용자의 신원 또는 특정 거래와 관련된 정보를 확인하기 위해 추가 문서를 요청할 수 있습니다. 2.4. 의심스러운 거래 또는 높은 AML 위험의 경우, 계약자는 신원 증명 서류를 들고 있는 사용자의 사진이나 동영상과 함께 적법한 자금 출처를 뒷받침하는 기타 증거를 요청할 수 있습니다.",
  "customer.madea3328508f": "2. 신원 확인",
  "customer.m470ce68e0179": "3.1. 계약자는 의심스러운 활동을 식별하기 위해 거래 통제 절차를 사용합니다. 거래에 추가 검토가 필요한 경우, 계약자는 자금 출처를 확인하는 동안 최대 14일까지 거래를 일시 중단할 수 있습니다. 3.2. 검토에는 다음이 포함될 수 있습니다: • web.amlbot.com과 같은 전문 AML 서비스를 사용하여 위험 지표 및 잠재적으로 불법적인 자금을 식별하는 거래 평가. • 사용자의 암호화폐 지갑 계정 스크린샷 또는 동영상 요청. • 가용 데이터, 파트너 시스템 및 법 집행 기관의 법적 요청을 사용하여 자금 출처 정보 분석. 3.3. 거래 위험이 허용 수준을 초과하는 경우, 계약자는 다음을 수행할 수 있습니다: • 최대 14일까지 자금 동결. • 플랫폼 보안 서비스의 확인이 완료된 후 자금이 전송된 세부 정보 또는 다른 세부 정보로 자금 반환.",
  "customer.m25cf0f1a6773": "3. 자금 출처 확인 및 거래 중단",
  "customer.mf005431428cf": "4.1. 플랫폼 이용 약관에 동의함으로써, 사용자는 자금이 적법한 출처에서 비롯되었음을 확인하며, 확인이 필요할 때 자금 출처에 대한 완전하고 정확하며 최신의 정보를 제공하는 데 동의합니다. 4.2. 사용자는 본 AML 정책의 요구 사항을 충족하는 데 합리적으로 필요한 정보를 제공함으로써 완전히 협조해야 합니다. 4.3. 자금 출처 정보를 제공하지 않거나 허위 또는 오해의 소지가 있는 정보를 제공하는 경우 자금이 동결될 수 있습니다. 적절한 경우, 계약자는 동결된 자금을 정당한 소유자에게 반환하는 데 도움이 되도록 법 집행 기관과 협력할 수 있습니다.",
  "customer.m6159cfab67f4": "4. 사용자 책임 및 협조",
  "customer.mc7653de88314": "5.1. 계약자는 오용을 방지하기 위한 조치를 취하며, 의심스러운 활동을 식별하고 차단하기 위해 거래 모니터링 방법을 사용합니다. 5.2. 사용자가 자금 출처를 적절히 입증할 수 없거나 범죄 행위가 의심되는 인물과 연관된 것으로 보이는 경우를 포함한 예외적인 상황에서, 계약자는 추가적인 신원 및 자금 출처 확인을 요구할 수 있습니다. 5.3. 사용자가 본 AML 정책을 준수하지 않는 경우, 계약자는 관련 법률 및 플랫폼 이용 약관에 따라 거래를 거부하거나 계약을 해지할 수 있습니다.",
  "customer.m3f129e8654c2": "5. 위반 방지를 위한 조치",
  "customer.mdb63766200b1": "6.1. 정책 위반, 허위 정보 제공 또는 협조 거부의 경우, 계약자는 다음을 수행할 수 있습니다: • 거래 수행 거부. • 확인이 완료될 때까지 자금 동결. • 범죄 활동과의 연관성이 확인되고 법적으로 공개가 허용되는 경우, 법 집행 기관에 거래 및 사용자 정보 제공. 6.2. 동결된 자금은 관련 당국의 적법한 요청에 따라 정당한 소유자에게 이전될 수 있습니다.",
  "customer.m0672388b59cf": "6. 미준수에 따른 결과",
  "customer.m9a74e91c19e6": "7.1. 사용자가 자금 출처에 대한 적절한 확인을 제공할 수 없는 경우, 계약자는 사용자의 활동 적법성을 평가하기 위해 필요한 추가 서류나 정보를 요청할 수 있습니다. 7.2. 불법 활동에 연루되었다는 합리적인 의심이 있는 경우, 계약자는 계정 액세스를 제한하고 법률에 의해 허용되거나 요구되는 경우 법 집행 기관에 관련 정보를 제공할 수 있습니다.",
  "customer.mcaca6ca4eaa2": "7. 예외적인 상황",
  "customer.m387717619832": "8.1. 계약자는 사용자를 보호하고 적용 가능한 AML 요구 사항을 충족하기 위해 합리적인 조치를 취할 것을 약속합니다. 8.2. 사용자는 플랫폼 요구 사항을 따르고, 신뢰할 수 있는 정보를 제공하며, 자신의 관할 구역에서 적용되는 법률을 준수해야 합니다. 본 AML 정책은 플랫폼 사용자를 위해 더 안전하고 투명한 환경을 지원합니다. 오용을 방지하고 신뢰를 유지하기 위해서는 사용자의 협조와 규정 준수가 필수적입니다.",
  "customer.m58409ec600ac": "8. 계약자와 사용자의 의무",
  "customer.mb5bc0b775628": "본 정책은 불법 금융 활동을 방지하고, 모든 사용자를 위한 금융 환경의 보안을 강화하며, 자금 세탁 방지 및 테러 자금 조달 금지에 관한 적용 가능한 요구 사항 준수를 지원하기 위해 설계되었습니다.",
  "customer.m358cc201f87d": "운영",
  "customer.m968c7b138992": "주문 조회",
  "customer.m41a5d223574b": "bitcoin-market",
  "customer.maf48f925f562": "okchanger-logo",
  "customer.m5a9b5eaa4cd2": "trustpilot-seeklogo",
